        ["g_forecast_below"] = new[] { "The balance is at or below the stop threshold {0}.", "Баланс на рівні або нижче порогу зупинки {0}.", "El saldo está en el umbral de parada {0} o por debajo.", "Das Guthaben liegt auf oder unter der Stopp-Schwelle {0}.", "Le solde est au seuil d'arrêt {0} ou en dessous.", "Il saldo è pari o sotto la soglia di arresto {0}.", "O saldo está no limite de parada {0} ou abaixo.", "Saldo jest na progu zatrzymania {0} lub poniżej.", "余额已等于或低于停止阈值 {0}。", "残高が停止しきい値 {0} 以下です。" },
