        ["g_no_balance"] = new[] { "no balance reading — the guard can't work", "немає даних про баланс — захист не працює", "sin lectura del saldo: la protección no funciona", "kein Guthaben lesbar – der Schutz wirkt nicht", "pas de lecture du solde — la garde ne fonctionne pas", "nessuna lettura del saldo — la protezione non funziona", "sem leitura do saldo — a proteção não funciona", "brak odczytu salda — ochrona nie działa", "无法获取余额——保护无法工作", "残高を取得できません — ガードは機能しません" },
