        ["g_off"] = new[] { "Auto-stop cancelled: the guard was turned off.", "Автозупинку скасовано: захист вимкнено.", "Parada automática cancelada: se desactivó la protección.", "Auto-Stopp abgebrochen: Schutz ausgeschaltet.", "Arrêt automatique annulé : la garde a été désactivée.", "Arresto automatico annullato: protezione disattivata.", "Parada automática cancelada: a proteção foi desativada.", "Automatyczne zatrzymanie anulowane: ochronę wyłączono.", "自动停止已取消：保护已关闭。", "自動停止を取り消しました: ガードがオフになりました。" },
        ["g_restart"] = new[] { "interrupted: TaskHub restarted", "перервано: TaskHub перезапущено", "interrumpido: TaskHub se reinició", "unterbrochen: TaskHub neu gestartet", "interrompu : TaskHub a redémarré", "interrotto: TaskHub riavviato", "interrompido: o TaskHub reiniciou", "przerwano: TaskHub uruchomiono ponownie", "已中断：TaskHub 已重启", "中断: TaskHub が再起動しました" },
        ["g_stopping"] = new[] { "Stopping now…", "Зупиняю…", "Deteniendo…", "Wird gestoppt…", "Arrêt en cours…", "Arresto in corso…", "Parando…", "Zatrzymuję…", "正在停止…", "停止しています…" },
        ["g_bad_values"] = new[] { "Not saved — check the values: the warning threshold must be above the auto-stop threshold ({0}).", "Не збережено — перевірте значення: поріг попередження має бути вищим за поріг автозупинки ({0}).", "No se guardó: revisa los valores; el umbral de aviso debe ser mayor que el de parada automática ({0}).", "Nicht gespeichert – bitte Werte prüfen: Die Warnschwelle muss über der Auto-Stopp-Schwelle liegen ({0}).", "Non enregistré — vérifiez les valeurs : le seuil d'alerte doit être au-dessus du seuil d'arrêt automatique ({0}).", "Non salvato — controlla i valori: la soglia di avviso deve essere sopra quella di arresto automatico ({0}).", "Não salvo — verifique os valores: o limite de aviso deve ficar acima do limite de parada automática ({0}).", "Nie zapisano — sprawdź wartości: próg ostrzeżenia musi być wyższy niż próg automatycznego zatrzymania ({0}).", "未保存——请检查数值：警告阈值必须高于自动停止阈值（{0}）。", "保存されませんでした — 値を確認してください: 警告しきい値は自動停止しきい値より上にする必要があります（{0}）。" },
        ["g_stop_now_q"] = new[] { "Stop {0} now? Stopped, not deleted: the disk / volume storage keeps billing.", "Зупинити {0} зараз? Машини зупиняються, не видаляються: сховище диска / тому й далі оплачується.", "¿Detener {0} ahora? Se detienen, no se eliminan: el almacenamiento del disco / volumen sigue cobrándose.", "{0} jetzt stoppen? Gestoppt, nicht gelöscht: Der Speicher von Disk / Volume wird weiter berechnet.", "Arrêter {0} maintenant ? Arrêtées, pas supprimées : le stockage du disque / volume reste facturé.", "Fermare {0} ora? Fermate, non eliminate: lo storage di disco / volume continua a essere addebitato.", "Parar {0} agora? Paradas, não excluídas: o armazenamento do disco / volume continua sendo cobrado.", "Zatrzymać teraz {0}? Zatrzymane, nie usunięte: magazyn dysku / wolumenu jest nadal naliczany.", "立即停止 {0}？只停止不删除：磁盘 / 卷存储仍会计费。", "{0} を今すぐ停止しますか？停止のみで削除はしません。ディスク / ボリュームのストレージは引き続き課金されます。" },
        ["g_probe_wait"] = new[] { "Balance {0} is below the auto-stop threshold {1}, but TaskHub hasn't been able to check yet whether the API key may stop machines — nothing is stopped for now; it tries again at the next reading.", "Баланс {0} нижче порогу автозупинки {1}, але TaskHub ще не зміг перевірити, чи може API-ключ зупиняти машини, — поки нічого не зупинено; повторить при наступному зчитуванні.", "El saldo {0} está por debajo del umbral de parada automática {1}, pero TaskHub aún no pudo comprobar si la clave de API puede detener máquinas: por ahora no se detiene nada; lo reintenta en la próxima lectura.", "Guthaben {0} liegt unter der Auto-Stopp-Schwelle {1}, aber TaskHub konnte noch nicht prüfen, ob der API-Schlüssel Maschinen stoppen darf – vorerst wird nichts gestoppt; nächster Versuch bei der nächsten Abfrage.", "Le solde {0} est sous le seuil d'arrêt automatique {1}, mais TaskHub n'a pas encore pu vérifier si la clé API peut arrêter les machines — rien n'est arrêté pour l'instant ; nouvel essai à la prochaine lecture.", "Il saldo {0} è sotto la soglia di arresto automatico {1}, ma TaskHub non ha ancora potuto verificare se la chiave API può fermare le macchine — per ora non si ferma nulla; riprova alla prossima lettura.", "O saldo {0} está abaixo do limite de parada automática {1}, mas o TaskHub ainda não conseguiu verificar se a chave de API pode parar máquinas — nada é parado por enquanto; tenta de novo na próxima leitura.", "Saldo {0} jest poniżej progu automatycznego zatrzymania {1}, ale TaskHub nie mógł jeszcze sprawdzić, czy klucz API może zatrzymywać maszyny — na razie nic nie zatrzymano; ponowi przy następnym odczycie.", "余额 {0} 低于自动停止阈值 {1}，但 TaskHub 尚未能确认 API 密钥是否可以停止机器——暂不停止任何机器；下次读取时重试。", "残高 {0} が自動停止しきい値 {1} を下回りましたが、API キーでマシンを停止できるかをまだ確認できていません — 今は何も停止しません。次回の読み取りで再試行します。" },
        ["g_nostop_postpaid"] = new[] { "This Runpod account is post-paid (invoiced afterwards): its balance isn't money left before a stop, so the guard only warns.", "Цей акаунт Runpod постоплатний (рахунок виставляється потім): його баланс — не гроші до зупинки, тож захист лише попереджає.", "Esta cuenta de Runpod es pospago (se factura después): su saldo no es dinero restante antes de una parada, así que la protección solo avisa.", "Dieses Runpod-Konto ist nachträglich abgerechnet (Post-paid): Das Guthaben ist kein Restgeld bis zum Stopp, der Schutz warnt daher nur.", "Ce compte Runpod est post-payé (facturé ensuite) : son solde n'est pas l'argent restant avant un arrêt, la protection se contente donc d'avertir.", "Questo account Runpod è post-pagato (fatturato dopo): il saldo non è denaro residuo prima di un arresto, quindi la protezione si limita ad avvisare.", "Esta conta Runpod é pós-paga (faturada depois): o saldo não é dinheiro restante antes de uma parada, então a proteção apenas avisa.", "To konto Runpod jest rozliczane z dołu (post-paid): saldo nie jest kwotą pozostałą do zatrzymania, więc ochrona tylko ostrzega.", "此 Runpod 账户为后付费（事后开票）：其余额不代表停止前剩余的钱，因此保护只发出警告。", "この Runpod アカウントは後払い（後日請求）です。残高は停止までの残金ではないため、ガードは警告のみ行います。" },
